import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { checkout } from './src/app.js';
import { makeReceiptKey as reportKey } from './src/reports/receipt.js';
import { makeReceiptKey as transportKey } from './src/transport/receipt.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['owner_file', 'owner_symbol', 'outbound_file', 'outbound_symbol', 'call_chain', 'example_key']);
assert.deepEqual(answer.call_chain.map(({ symbol }) => symbol), ['checkout', 'submitInvoice', 'makeReceiptKey', 'sendInvoice']);
for (const { file, symbol } of answer.call_chain) {
  const module = await import('./' + file);
  assert.equal(typeof module[symbol], 'function', file + ':' + symbol);
}
assert.deepEqual(answer.call_chain[2], { file: answer.owner_file, symbol: answer.owner_symbol });
assert.deepEqual(answer.call_chain[3], { file: answer.outbound_file, symbol: answer.outbound_symbol });

const invoice = { accountId: 'acme', sequence: 7 };
let outbound;
const result = await checkout(invoice, { post: async (...args) => { outbound = args; return 'sent'; } });
assert.equal(result, 'sent');
assert.deepEqual(outbound, ['/invoices', invoice, { 'Idempotency-Key': answer.example_key }]);
assert.equal(answer.example_key, 'invoice/acme/0007');
assert.equal(reportKey({ id: 'row1' }), 'report:row1');
assert.equal(transportKey({ headers: { 'x-receipt': 'upstream-receipt' } }), 'upstream-receipt');
console.log('PASS: answer schema, symbol paths, checkout outbound header, and distinct receipt helpers');
NODE"

